<?php

namespace Tests\Unit\MapsNavigation;

use PHPUnit\Framework\TestCase;

/**
 * Checks the map package written by tools/blender/ism_map.py against the
 * MapsNavigation business rules, using the committed pilot sample. The sample
 * is regenerated by tests/Blender/test_ism_map.py --write-sample, so a change to
 * the exporter that breaks the contract fails here.
 */
class MapPackageContractTest extends TestCase
{
    private const SAMPLE = __DIR__.'/../../../tools/blender/samples/pilot_map_package.json';

    private const NODE_TYPES = ['junction', 'entrance', 'checkpoint', 'connector', 'facility'];

    private const FACILITY_TYPES = ['toilet', 'prayer_room', 'information', 'exit', 'atm', 'lift', 'other'];

    /**
     * @var array<string, mixed>
     */
    private array $package;

    protected function setUp(): void
    {
        parent::setUp();

        $this->package = json_decode((string) file_get_contents(self::SAMPLE), true, flags: JSON_THROW_ON_ERROR);
    }

    public function test_header_declares_format_and_coordinate_conventions(): void
    {
        $this->assertSame('ism-map-package', $this->package['format']);
        $this->assertSame(1, $this->package['format_version']);
        $this->assertStringStartsWith('ism-mall-local-v1: metres', $this->package['coordinate_frame']);
        $this->assertStringContainsString('z up', $this->package['coordinate_frame']);
        $this->assertStringContainsString('(gltf_x, gltf_y, gltf_z) = (x, z, -y)', $this->package['glb_axes']);
        $this->assertStringContainsString('top-left', $this->package['plan_transform']);
    }

    public function test_floors_have_unique_codes_levels_and_a_valid_plan_transform(): void
    {
        $floors = $this->package['floors'];
        $this->assertNotEmpty($floors);
        $this->assertSame(count($floors), count(array_unique(array_column($floors, 'floor_code'))));
        $this->assertSame(count($floors), count(array_unique(array_map('strval', array_column($floors, 'elevation_m')))));

        foreach ($floors as $floor) {
            $this->assertLessThanOrEqual(20, strlen($floor['floor_code']));
            $this->assertGreaterThan(0, $floor['plan']['metres_per_pixel']);
            $this->assertGreaterThan(0, $floor['plan']['width_px']);
            $this->assertGreaterThan(0, $floor['plan']['height_px']);
            $this->assertSame(0, $floor['plan']['rotation_deg']);
            $this->assertStringEndsWith('.png', $floor['plan']['file']);
            $this->assertStringEndsWith('.glb', $floor['model']['file']);
        }
    }

    public function test_nodes_have_unique_codes_known_types_and_sit_on_their_floor(): void
    {
        $elevations = array_column($this->package['floors'], 'elevation_m', 'floor_code');
        $codes = array_column($this->package['nodes'], 'node_code');

        $this->assertSame(count($codes), count(array_unique($codes)));

        foreach ($this->package['nodes'] as $node) {
            $this->assertLessThanOrEqual(50, strlen($node['node_code']));
            $this->assertContains($node['node_type'], self::NODE_TYPES);
            $this->assertArrayHasKey($node['floor_code'], $elevations);
            $this->assertEqualsWithDelta($elevations[$node['floor_code']], $node['z_m'], 1e-6);
        }
    }

    public function test_edges_follow_the_navigation_edge_rules(): void
    {
        $nodes = $this->nodesByCode();
        $stops = [];
        foreach ($this->package['connectors'] as $connector) {
            $stops[$connector['name']] = array_column($connector['stops'], 'node_code');
        }
        $pairs = [];

        foreach ($this->package['edges'] as $edge) {
            $from = $nodes[$edge['from_node_code']] ?? null;
            $to = $nodes[$edge['to_node_code']] ?? null;
            $this->assertNotNull($from, "unknown node {$edge['from_node_code']}");
            $this->assertNotNull($to, "unknown node {$edge['to_node_code']}");
            $this->assertNotSame($edge['from_node_code'], $edge['to_node_code']);
            $this->assertGreaterThan(0, $edge['length_m']);
            $this->assertGreaterThan(0, $edge['expected_seconds']);
            $this->assertContains($edge['status'], ['open', 'temporarily_closed']);

            $pair = $edge['from_node_code'].'>'.$edge['to_node_code'];
            $this->assertArrayNotHasKey($pair, $pairs, "duplicate edge {$pair}");
            $pairs[$pair] = true;

            if ($edge['connector'] === null) {
                $this->assertSame($from['floor_code'], $to['floor_code'], "walking edge {$pair} changes floor");

                continue;
            }

            $this->assertNotSame($from['floor_code'], $to['floor_code']);
            $this->assertContains($edge['from_node_code'], $stops[$edge['connector']]);
            $this->assertContains($edge['to_node_code'], $stops[$edge['connector']]);
            $this->assertGreaterThanOrEqual(abs($to['z_m'] - $from['z_m']) - 1e-6, $edge['length_m']);
        }
    }

    public function test_connectors_serve_distinct_floors_and_escalators_run_one_way(): void
    {
        $nodes = $this->nodesByCode();

        foreach ($this->package['connectors'] as $connector) {
            $this->assertContains($connector['connector_type'], ['elevator', 'escalator', 'stairs']);
            $this->assertGreaterThanOrEqual(2, count($connector['stops']));
            $floors = array_column($connector['stops'], 'floor_code');
            $this->assertSame(count($floors), count(array_unique($floors)));

            foreach ($connector['stops'] as $stop) {
                $this->assertSame('connector', $nodes[$stop['node_code']]['node_type']);
                $this->assertSame($stop['floor_code'], $nodes[$stop['node_code']]['floor_code']);
            }

            if ($connector['connector_type'] === 'escalator') {
                $this->assertContains($connector['direction'], ['up', 'down']);
                $edges = array_filter($this->package['edges'], fn (array $edge): bool => $edge['connector'] === $connector['name']);
                foreach ($edges as $edge) {
                    $rises = $nodes[$edge['to_node_code']]['z_m'] > $nodes[$edge['from_node_code']]['z_m'];
                    $this->assertSame($connector['direction'] === 'up', $rises);
                }
            }
        }
    }

    public function test_checkpoints_anchor_a_qr_face_to_a_checkpoint_node(): void
    {
        $nodes = $this->nodesByCode();
        $codes = array_column($this->package['checkpoints'], 'checkpoint_code');

        $this->assertNotEmpty($codes);
        $this->assertSame(count($codes), count(array_unique($codes)));

        foreach ($this->package['checkpoints'] as $checkpoint) {
            $node = $nodes[$checkpoint['node_code']];
            $this->assertSame('checkpoint', $node['node_type']);
            $this->assertSame($checkpoint['floor_code'], $node['floor_code']);
            $this->assertGreaterThanOrEqual(0, $checkpoint['qr']['yaw_deg']);
            $this->assertLessThan(360, $checkpoint['qr']['yaw_deg']);
            $this->assertGreaterThan(0, $checkpoint['qr']['marker_height_m']);
            $this->assertGreaterThan(0, $checkpoint['qr']['physical_width_m']);
            $this->assertEqualsWithDelta($node['z_m'] + $checkpoint['qr']['marker_height_m'], $checkpoint['qr']['z_m'], 1e-3);
        }
    }

    public function test_shop_entrances_and_facilities_bind_to_typed_nodes(): void
    {
        $nodes = $this->nodesByCode();
        $primary = [];

        foreach ($this->package['shop_entrances'] as $entrance) {
            $node = $nodes[$entrance['node_code']];
            $this->assertSame('entrance', $node['node_type']);
            $this->assertSame($entrance['floor_code'], $node['floor_code']);
            $this->assertLessThanOrEqual(40, strlen($entrance['unit_code']));
            if ($entrance['is_primary']) {
                $primary[$entrance['unit_code']] = ($primary[$entrance['unit_code']] ?? 0) + 1;
            }
        }
        $this->assertSame(array_fill_keys(array_unique(array_column($this->package['shop_entrances'], 'unit_code')), 1), $primary);

        foreach ($this->package['facility_anchors'] as $facility) {
            $this->assertContains($facility['facility_type'], self::FACILITY_TYPES);
            $this->assertSame('facility', $nodes[$facility['node_code']]['node_type']);
        }
    }

    public function test_every_destination_is_reachable_from_every_checkpoint(): void
    {
        $outgoing = [];
        foreach ($this->package['edges'] as $edge) {
            $outgoing[$edge['from_node_code']][] = $edge['to_node_code'];
        }
        $destinations = array_merge(
            array_column($this->package['shop_entrances'], 'node_code'),
            array_column($this->package['facility_anchors'], 'node_code'),
        );

        foreach ($this->package['checkpoints'] as $checkpoint) {
            $seen = [$checkpoint['node_code'] => true];
            $queue = [$checkpoint['node_code']];
            while ($queue !== []) {
                foreach ($outgoing[array_shift($queue)] ?? [] as $next) {
                    if (! isset($seen[$next])) {
                        $seen[$next] = true;
                        $queue[] = $next;
                    }
                }
            }

            foreach ($destinations as $destination) {
                $this->assertArrayHasKey($destination, $seen, "{$destination} unreachable from {$checkpoint['checkpoint_code']}");
            }
        }
    }

    /**
     * @return array<string, array{node_code: string, floor_code: string, node_type: string, x_m: float, y_m: float, z_m: float, is_accessible: bool}>
     */
    private function nodesByCode(): array
    {
        return array_column($this->package['nodes'], null, 'node_code');
    }
}
